'use strict';
const team=[['Forge','AI CEO','Leadership and education','Hosts practical AI education, explains the ecosystem and presents the company direction. Forge is a brand character; business accountability stays with the owner.'],['Maya','Client Success','Your everyday contact','Understands priorities, keeps the brief coherent and explains progress. Maya brings in specialists when needed so the client has one familiar relationship.'],['Atlas','Technology','Websites, apps and automation','Turns a technical brief into a scoped plan, coordinates implementation and checks integrations. Custom work requires an agreed scope.'],['Nova','Creative','Design and content direction','Shapes visuals, copy and presentation around the client’s approved brand information. Coordinates creative specialists and review rounds.'],['Leo','Marketing','Campaigns and publishing','Plans channel-specific content, coordinates production and reviews campaign results. Publishing requires a connected account and agreed permissions.'],['Iris','Operations','Keeping the work connected','Assigns tasks, manages dependencies and tracks milestones. Missing information, delays and failed connections should be surfaced rather than hidden.'],['Ledger','Finance','Billing and finance support','Explains package capacity and billing. Supports invoice preparation and financial organization; authoritative calculations belong in accounting software.'],['Sage','Research','Useful information, clearly explained','Reviews documents, gathers sources and maintains approved business knowledge. Recommendations should distinguish evidence from assumptions.'],['Orion','Quality','Check before delivery','Reviews outputs against the brief, checks facts and flags issues. Technical work also needs appropriate automated and functional checks.'],['Amara','Onboarding','A clear place to start','Collects business information, assets and preferences, then prepares a starting brief. This draft uses a browser-local guided form, not a live AI connection.']];
const $=s=>document.querySelector(s);const detail=$('#detail-dialog');
function showDetail(title,description,items=[]){const body=$('#detail-body');body.replaceChildren();const tag=document.createElement('div');tag.className='eyebrow';tag.textContent='AGENTICCORE / OFFICE CONCEPT';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=description;body.append(tag,h,p);if(items.length){const ul=document.createElement('ul');items.forEach(x=>{const li=document.createElement('li');li.textContent=x;ul.append(li)});body.append(ul)}detail.showModal()}
team.forEach((t,i)=>{const b=document.createElement('button');b.className='person';b.setAttribute('aria-label',`Meet ${t[0]}, ${t[1]}`);b.innerHTML=`<div class="portrait" style="--x:${(i%5)*25}%;--y:${i<5?'23':'91'}%" aria-hidden="true"></div><h3>${t[0]} <span aria-hidden="true">↗</span></h3><p>${t[1]}</p>`;b.onclick=()=>showDetail(`${t[0]} · ${t[1]}`,t[3],[t[2],'Proposed AI role and visual identity. Connected execution is planned.']);$('#team-grid').append(b)});
const challenges=[{name:'Marketing',title:'Show up consistently.',text:'Turn your approved offers and brand assets into a planned batch of content, rather than starting from scratch every day.',tasks:['An agreed content calendar','Channel-specific captions and visual concepts','Review, publishing permissions and reporting'],lead:'Leo + Nova',need:'marketing'},{name:'Enquiries',title:'Give every enquiry a next step.',text:'A supported receptionist workflow can answer approved questions, gather useful details and route enquiries that need a person.',tasks:['Answers from approved business information','Lead details and qualification','Clear handover and enquiry summaries'],lead:'Maya + Iris',need:'enquiries'},{name:'Websites & systems',title:'Connect the things that should work together.',text:'Define your website or automation brief, identify the right connections and scope a useful first delivery.',tasks:['A clear technical brief','Agreed scope and milestones','Testing and delivery documentation'],lead:'Atlas + Orion',need:'technology'},{name:'Administration',title:'Make room for the work you enjoy.',text:'Organize repeatable administration into defined tasks with useful reminders and visible ownership.',tasks:['Document collection and organization','Routine summaries and preparation','Task tracking and reminders'],lead:'Iris + Ledger',need:'admin'},{name:'Starting out',title:'Start with a team-shaped plan.',text:'Identify the practical foundations your business needs, then choose a manageable first piece of work.',tasks:['Business priorities and approved information','A starter website or materials brief','A realistic first-month work plan'],lead:'Amara + Maya',need:'start'}];
challenges.forEach((c,i)=>{const b=document.createElement('button');b.role='tab';b.id='challenge-'+i;b.setAttribute('aria-controls','problem-content');b.textContent=c.name;b.onclick=()=>selectChallenge(i);b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const n=(i+(e.key==='ArrowRight'?1:-1)+challenges.length)%challenges.length;selectChallenge(n);$('#challenge-'+n).focus()}};$('.problem-tabs').append(b)});
function selectChallenge(i){const c=challenges[i];document.querySelectorAll('.problem-tabs button').forEach((b,n)=>{b.setAttribute('aria-selected',n===i);b.tabIndex=n===i?0:-1});$('#problem-content').setAttribute('aria-labelledby','challenge-'+i);$('#problem-content').innerHTML=`<div><div class="label">YOUR CHALLENGE / ${c.name}</div><h3>${c.title}</h3><p>${c.text}</p><button id="challenge-start">Build my starting brief ↗</button></div><div><div class="label">EXAMPLE SUPPORT / ${c.lead}</div><ul>${c.tasks.map(x=>`<li>${x}</li>`).join('')}</ul><p class="fine">Illustrative scope. Availability and allowances depend on the service agreed.</p></div>`;$('#challenge-start').onclick=()=>openAssessment(c.need)}selectChallenge(0);
const journey=[['Understand the request','Maya','“We’re launching a new offer next week.”','Maya asks for the offer, audience, channels and approved product facts.','Output: an editable campaign brief.'],['Plan and assign','Iris','One brief. Clear responsibilities.','Iris checks scope and capacity, then assigns copy and visuals with a review milestone.','Output: a work plan with dependencies.'],['Create the campaign','Leo + Nova','The right format for each channel.','The team prepares captions and visual concepts using the approved brand assets.','Output: a draft batch, not published posts.'],['Check and approve','Orion + Client','Review before release.','Orion checks claims and requirements. The client reviews the batch and approves publishing where required.','Output: approved content and recorded decisions.'],['Deliver and report','Maya','Your work has a visible outcome.','The connected publishing tool would schedule approved posts, confirm results and report failures. Maya prepares a clear summary.','Output: recorded results and next actions.']];
journey.forEach((j,i)=>{const b=document.createElement('button');b.innerHTML=`<span>0${i+1}</span>${j[0]}`;b.onclick=()=>selectStep(i);$('#steps').append(b)});function selectStep(i){document.querySelectorAll('#steps button').forEach((b,n)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-pressed',i===n)});const j=journey[i];$('#work-detail').innerHTML=`<div class="label">STEP 0${i+1} / ${j[1]}</div><h3>${j[2]}</h3><p>${j[3]}</p><div class="work-note">${j[4]}</div>`}selectStep(0);
const assessment=$('#assessment');function openAssessment(need){const route=$('#brief-form').elements.serviceRoute;route.value='managed';route.dispatchEvent(new Event('change'));if(need)$('#brief-form').elements.need.value=need;assessment.showModal()}document.querySelectorAll('[data-assess]').forEach(b=>b.onclick=()=>openAssessment());document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$('#privacy').onclick=()=>showDetail('Privacy & this concept edition','This draft creates recommendations in your browser. It has no enquiry submission, payment, analytics or connected messaging backend. Assessment text is not saved by this page after a reload unless you download it.',['Downloaded briefs are saved on your device. Avoid entering confidential information.','External service links open other websites with their own policies.','A complete business privacy notice and service terms are needed before connected onboarding launches.','AI team portraits are conceptual brand illustrations. Subscription prices and execution workflows are proposals.']);
$('#brief-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const c=challenges.find(x=>x.need===f.get('need'));const owned=f.get('serviceRoute')==='owned';const office=owned?window.ownedOfficeSelection:window.officeSelection;const destination=owned?'Agenticcore Group — company-owned framework build':'Agenticcore Group — managed office package';const text=`AGENTICCORE — MY STARTING BRIEF\n\nBusiness / idea: ${f.get('business').trim()}\nPriority: ${c.name}\nPayment preference: ${f.get('relationship')}\nPreferred update channel: ${f.get('channel')}\nBudget for selected service: ${f.get('budget')}\nDesired result: ${f.get('goal').trim()||'To be clarified'}\n\nSuggested leads: ${c.lead}\nSuggested starting work: ${c.tasks[0]}\nPotential route: ${destination}\n\n${office?office.text:'Office departments: to be selected'}\n\nBefore work starts: confirm approved business information, scope, deliverables, capacity, turnaround and permissions.\n\nThis is a rule-based recommendation from a concept website. It has not been submitted or accepted as an order. Builder figures are proposed estimates, not a confirmed quote. Proposed packages and custom builds are not yet purchasable.`;const out=$('#brief-result');out.replaceChildren();const h=document.createElement('h3');h.textContent='Your proposed office brief';const pre=document.createElement('pre');pre.textContent=text;const download=document.createElement('button');download.className='dark';download.textContent='Download my brief ↓';download.type='button';download.onclick=()=>{const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='agenticcore-office-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};out.append(h,pre,download);out.hidden=false;out.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
